#!/bin/bash
# Generated by train_jobs.py — regenerate instead of editing array ranges.
# train_jobs: resource_profile=small
# train_jobs: job_indices=0,1,2,3,4,5,15,16,17,18,19,20,30,31,32,33,34,35,45,46,47,48,49,50
#
# SLURM_ARRAY_TASK_ID selects jobs.jsonl index (not feeder/grid id):
#   [0] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho10
#   [1] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho10
#   [2] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho10
#   [3] grid=123 suffix=default  IEEE123Master_penalty_direct_rho10
#   [4] grid=123 suffix=default  IEEE123Master_penalty_direct_rho10
#   [5] grid=123 suffix=default  IEEE123Master_penalty_direct_rho10
#   [15] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho100
#   [16] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho100
#   [17] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho100
#   [18] grid=123 suffix=default  IEEE123Master_penalty_direct_rho100
#   [19] grid=123 suffix=default  IEEE123Master_penalty_direct_rho100
#   [20] grid=123 suffix=default  IEEE123Master_penalty_direct_rho100
#   [30] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho500
#   [31] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho500
#   [32] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho500
#   [33] grid=123 suffix=default  IEEE123Master_penalty_direct_rho500
#   [34] grid=123 suffix=default  IEEE123Master_penalty_direct_rho500
#   [35] grid=123 suffix=default  IEEE123Master_penalty_direct_rho500
#   [45] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho1000
#   [46] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho1000
#   [47] grid=13 suffix=default  IEEE13Nodeckt_penalty_direct_rho1000
#   [48] grid=123 suffix=default  IEEE123Master_penalty_direct_rho1000
#   [49] grid=123 suffix=default  IEEE123Master_penalty_direct_rho1000
#   [50] grid=123 suffix=default  IEEE123Master_penalty_direct_rho1000
# Submit without overriding --array; use train_jobs.py verify after regenerate.
#SBATCH --requeue
#SBATCH --job-name=train_penalty_direct
#SBATCH --output=logs/training/penalty_direct/%A_%a.out
#SBATCH --error=logs/training/penalty_direct/%A_%a.err
#SBATCH --array=0,1,2,3,4,5,15,16,17,18,19,20,30,31,32,33,34,35,45,46,47,48,49,50%8
#SBATCH --time=12:00:00
#SBATCH --cpus-per-task=4
#SBATCH --mem=32G
#SBATCH -G h200:1
#SBATCH --partition=pi_donti_gpu,mit_preemptable

set -euo pipefail

if [ -n "${SLURM_SUBMIT_DIR:-}" ] && [ -f "$SLURM_SUBMIT_DIR/scripts/slurm_runs/train_jobs.py" ]; then
  PROJECT_DIR="$SLURM_SUBMIT_DIR"
else
  SUBMIT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
  PROJECT_DIR="$(cd "$SUBMIT_DIR/../../.." && pwd)"
fi
cd "$PROJECT_DIR"

if [ ! -f "$PROJECT_DIR/scripts/slurm_runs/train_jobs.py" ]; then
  echo "ERROR: repository root not found at $PROJECT_DIR" >&2
  echo "Run sbatch from the repository root (see scripts/slurm_runs/README.md)." >&2
  exit 1
fi

set +u
if [ -f "${CONDA_EXE%/*}/../etc/profile.d/conda.sh" ]; then
  source "${CONDA_EXE%/*}/../etc/profile.d/conda.sh"
elif [ -f "$HOME/miniconda3/etc/profile.d/conda.sh" ]; then
  source "$HOME/miniconda3/etc/profile.d/conda.sh"
elif [ -f "$HOME/anaconda3/etc/profile.d/conda.sh" ]; then
  source "$HOME/anaconda3/etc/profile.d/conda.sh"
else
  echo "ERROR: conda.sh not found" >&2
  exit 1
fi
conda activate new_opt
set -u

JOBS_FILE="$PROJECT_DIR/scripts/slurm_runs/penalty_direct/jobs.jsonl"
TASK_ID="${SLURM_ARRAY_TASK_ID:?SLURM_ARRAY_TASK_ID not set}"

case "$TASK_ID" in
  0|1|2|3|4|5|15|16|17|18|19|20|30|31|32|33|34|35|45|46|47|48|49|50) ;;
  *)
    echo "ERROR: SLURM_ARRAY_TASK_ID=$TASK_ID is not allowed for $(basename "${BASH_SOURCE[0]}")" >&2
    echo "Allowed jobs.jsonl indices: 0 1 2 3 4 5 15 16 17 18 19 20 30 31 32 33 34 35 45 46 47 48 49 50" >&2
    echo "Regenerate with train_jobs.py generate and sbatch this script without --array overrides." >&2
    exit 1
    ;;
esac

python "$PROJECT_DIR/scripts/slurm_runs/train_jobs.py" run --jobs "$JOBS_FILE" --index "$TASK_ID" --expect-resource-profile small

